@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}h2{margin:0 0 70px;font-size:100px;line-height:.95;letter-spacing:-.045em;font-weight:var(--rf-heading-weight)}
.tl{position:relative;padding-left:90px}
